Section STRCMP.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (e t rest1 rest2 : list Z) (lo : Z).
  Hypothesis E1 : bytes_at bsegs m (bv_unsigned a0) (map b8 (e ++ 0 :: rest1)).
  Hypothesis FE : Forall (fun c => 0 < c < 256) e.
  Hypothesis E2 : bytes_at bsegs m (bv_unsigned a1) (map b8 (t ++ 0 :: rest2)).
  Hypothesis FT : Forall (fun c => 0 < c < 256) t.
  Hypothesis ACC1 : accessible m (bv_unsigned a0) (Z.of_nat (length e) + 1).
  Hypothesis ACC2 : accessible m (bv_unsigned a1) (Z.of_nat (length t) + 1).
  Hypothesis SV1 : shvis m (bv_unsigned a0) (bv_unsigned a0 + Z.of_nat (length e) + 1).
  Hypothesis SV2 : shvis m (bv_unsigned a1) (bv_unsigned a1 + Z.of_nat (length t) + 1).
  Hypothesis ST0 : stk bsegs m lo (bv_unsigned sp).
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - AINTRIN_STACK.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis AC : ACONST m.
  Hypothesis N40a : Z.of_nat (length e) + 1 <= 2^40.
  Hypothesis N40b : Z.of_nat (length t) + 1 <= 2^40.
  Hypothesis INM1 : in_app_mem (bv_unsigned a0) (bv_unsigned a0 + Z.of_nat (length e) + 1).
  Hypothesis INM2 : in_app_mem (bv_unsigned a1) (bv_unsigned a1 + Z.of_nat (length t) + 1).
  Hypothesis DJ1 : bv_unsigned a0 + Z.of_nat (length (e ++ 0 :: rest1)) <= lo \/ bv_unsigned sp <= bv_unsigned a0.
  Hypothesis DJ2 : bv_unsigned a1 + Z.of_nat (length (t ++ 0 :: rest2)) <= lo \/ bv_unsigned sp <= bv_unsigned a1.
  Hypothesis CFIm : rw_cells bsegs m ACF_ISTRCMP_CELL [C1 (b8 1)].

  Notation p1 := (bv_unsigned a0).
  Notation p2 := (bv_unsigned a1).
  Notation lne := (Z.of_nat (length e)).
  Notation lnt := (Z.of_nat (length t)).
  Notation POST := (astrcmp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc (zstrcmp e t) lo m).
  Notation SP2 := (Z_to_bv 64 (bv_unsigned sp + -2192)).
  Notation W := [(bv_unsigned sp - 4096, bv_unsigned sp)].
  (* [comment removed for export] *)
  Notation RST pc x1 x5 x10 x11 x12 x13 x14 x15 x16 x17 x20 x21 x22 x23 x24 x25 x26 x27 mm :=
    (MS (mkR x1 SP2 gp tp x5 t1 t2 sp a1 x10 x11 x12 x13 x14 x15 x16 x17 a0 ra x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mm (seg_rom bsegs)).
  Notation FRAME mm := (rw_cells bsegs mm (bv_unsigned sp + -104)
                         [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
  Notation CF := (Z_to_bv 64 1831656).   (* [comment removed for export] *)

  Ltac prep :=
    intros; acb; unfold AINTRIN_STACK, ACF_STRICT_CELL, ACF_ISTRCMP_CELL in *;
    pose proof INM1 as INM1'; unfold in_app_mem, AHI_LO, AAPP_HI in INM1'; rewrite ASHADOW_BASE_val in INM1';
    pose proof INM2 as INM2'; unfold in_app_mem, AHI_LO, AAPP_HI in INM2'; rewrite ASHADOW_BASE_val in INM2';
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
    pose proof (bv_unsigned_in_range 64 a0) as A0R; unfold bv_modulus in A0R; change (2 ^ Z.of_N 64) with (2^64) in A0R;
    pose proof (bv_unsigned_in_range 64 a1) as A1R; unfold bv_modulus in A1R; change (2 ^ Z.of_N 64) with (2^64) in A1R.

  Lemma len1 : Z.of_nat (length (e ++ 0 :: rest1)) = lne + 1 + Z.of_nat (length rest1).
  Proof. rewrite length_app. cbn [length]. lia. Qed.
  Lemma len2 : Z.of_nat (length (t ++ 0 :: rest2)) = lnt + 1 + Z.of_nat (length rest2).
  Proof. rewrite length_app. cbn [length]. lia. Qed.

  (* [comment removed for export] *)
  Section K.
    Variables (i CH1 CH2 : Z).
    Hypothesis HC : 0 <= CH1 < 256 /\ 0 <= CH2 < 256.
    Hypothesis HI : 0 <= i /\ i <= lne /\ i <= lnt.
    Hypothesis SIGN : zstrcmp e t = (if CH1 <? CH2 then -1 else if CH2 <? CH1 then 1 else 0).

    (* [comment removed for export] *)
    Section JF.
      Variables (mm : word -> option byte) (fjunk : list byte).
      Hypothesis MIm : mem_inv bsegs mm.
      Hypothesis FR1 : FRAME mm.
      Hypothesis FR : rw_cells bsegs mm (bv_unsigned sp + -2192) [CB 2088 fjunk].
      Hypothesis STm : stk bsegs mm lo (bv_unsigned sp + -2192).
      Hypothesis MU : munch W m mm.
      Hypothesis WM : wmono bsegs m mm.

      (* [comment removed for export] *)
      Lemma sc_jf : forall x1 x5 x10 x11 x12 x13 x14 x15 x16 x17 x20 x21 x22 x23 x24 x27,
